<?php $title='Users';require __DIR__.'/_layout.php';if(!can_manage('users'))exit('Forbidden');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$st=db()->prepare("INSERT INTO users(name,email,password_hash,role,status) VALUES(?,?,?,?,'active')");$st->execute([trim($_POST['name']),trim($_POST['email']),password_hash($_POST['password'],PASSWORD_DEFAULT),$_POST['role']]);flash('success','User created.');redirect('users.php');}$rows=db()->query("SELECT id,name,email,role,status,created_at FROM users ORDER BY id DESC")->fetchAll();?><h1>Users</h1><form class="form" method="post"><?=csrf_field()?><input name="name" placeholder="Name" required><input name="email" type="email" placeholder="Email" required><input name="password" type="password" minlength="8" placeholder="Password" required><select name="role"><option>user</option><option>author</option><option>editor</option><option>admin</option><option>super_admin</option></select><button>Create user</button></form><table class="table"><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['role'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table><?php require __DIR__.'/_footer.php';?>